function drawPhotoThumbs(){const target=document.querySelector('#photo-thumbs');if(!target)return;target.innerHTML=state.editorSources.map(source=>`<div class="photo-thumb">${source.mime_type?.startsWith('image/')?`<a href="${e(source.url)}" target="_blank" rel="noopener"><img src="${e(source.url)}" alt="${e(source.filename)}"></a>`:`<a class="photo-tile" href="${e(source.url)}" target="_blank" rel="noopener" aria-label="Open ${e(source.filename)}">${icon('document')}</a>`}<button class="icon-button" type="button" data-action="remove-photo" data-id="${e(source.id)}" aria-label="Remove ${e(source.filename)} from this item">${icon('close')}</button></div>`).join('');}
function setEditorBusy(busy){
  state.editorBusy=busy;
  editor.querySelectorAll('#item-form [type=submit], #food-photos, #paste-photos').forEach(control=>{control.disabled=busy;});
}
function photoMessage(message){const target=editor.querySelector('#photo-status');if(target)target.textContent=message;}
async function pastePhotos(){
  if(!editor.open||state.editorBusy)return;
  if(!navigator.clipboard?.read){photoMessage('Press Ctrl+V (⌘V on Mac) to paste a copied image in this editor, or use Add photos.');return;}
  const form=editor.querySelector('#item-form');
  setEditorBusy(true);
  photoMessage('Reading the copied image…');
  const files=[];
  try{
    const items=await navigator.clipboard.read();
    for(const item of items){
      const type=['image/png','image/jpeg','image/webp'].find(type=>item.types.includes(type));
      if(!type)continue;
      const blob=await item.getType(type);
      const extension=type==='image/jpeg'?'jpg':type.split('/')[1];
      files.push(new File([blob],`pasted-image-${Date.now()}-${files.length+1}.${extension}`,{type}));
    }
    if(!files.length)photoMessage('No image was found. Copy the image itself, then paste again, or use Add photos.');
  }catch{photoMessage('Image pasting was unavailable. Try Ctrl+V (⌘V on Mac) in this editor, or use Add photos.');}
  finally{setEditorBusy(false);}
  if(editor.open&&editor.querySelector('#item-form')===form&&files.length)await uploadPhotos(files);
}
async function uploadPhotos(files){
  if(!files.length||!editor.open)return;
  if(state.editorBusy){photoMessage('Please wait for the current save to finish, then paste your next image.');return;}
  setEditorBusy(true);
  const input=editor.querySelector('#food-photos'),status=editor.querySelector('#photo-status'),warnings=[];
  let saved=0;
  try{
    for(let i=0;i<files.length;i++){
      const file=files[i];
      if(file.type&&!['image/jpeg','image/png','image/webp'].includes(file.type)){warnings.push(`${file.name}: Use a JPG, PNG, or WebP image.`);continue;}
      status.innerHTML=loading(`Saving photo ${i+1} of ${files.length}…`);
      try{
        const form=new FormData();form.append('file',file);form.append('purpose','photo');
        const source=await api('/api/uploads',{method:'POST',body:form});
        if(!state.editorSources.some(existing=>String(existing.id)===String(source.id)))state.editorSources.push(source);
        saved++;drawPhotoThumbs();status.innerHTML=loading(`Reading ${file.name}…`);
        try{
          const result=await api(`/api/sources/${encodeURIComponent(source.id)}/extract`,{method:'POST',body:'{}'});
          const suggestion=result.nutrition_suggestions;
          if(suggestion?.values?.length){state.nutritionSuggestion=suggestion;drawSuggestions();}
          warnings.push(...(result.warnings||[]));
        }catch(err){warnings.push(`${file.name}: ${err.message} Your original photo is saved.`);}
      }catch(err){warnings.push(`${file.name}: ${err.message}`);}
    }
    status.innerHTML=`${saved?'Photos attached. Review any suggested nutrition values, then save this food.':''}${warnings.length?`<div class="alert">${warnings.map(e).join('<br>')}</div>`:''}`;
  }finally{setEditorBusy(false);input.value='';}
}
editor.addEventListener('paste',event=>{
  if(!editor.open)return;
  const data=event.clipboardData;
  const files=[...(data?.files||[])];
  if(!files.length)for(const item of data?.items||[]){if(item.kind==='file'){const file=item.getAsFile();if(file)files.push(file);}}
  const images=files.filter(file=>file.type.startsWith('image/'));
  if(!images.length)return;
  event.preventDefault();
  void uploadPhotos(images);
});
function drawSuggestions(){const s=state.nutritionSuggestion;document.querySelector('#nutrition-suggestions').innerHTML=`<div class="ocr-suggestion"><h4>Some label details to review</h4><p>These are suggestions from your photo. Applying them replaces the nutrition fields below.</p><div class="ocr-values">${e(s.basis||'Basis not detected')}${s.serving_size?` · ${e(s.serving_size)}`:''}<br>${s.values.map(v=>`${e(v.label)}: ${e(v.value)} ${e(v.unit)}`).join(' · ')}</div><button class="button secondary" type="button" data-action="apply-nutrition">Use these values for review</button></div>`;}
async function saveItem(event){event.preventDefault();if(state.editorBusy)return;const form=event.target,button=form.querySelector('[type=submit]'),error=document.querySelector('#item-error');error.innerHTML='';const fd=new FormData(form);const values=[...form.querySelectorAll('.nutrition-input-row')].map(row=>({label:row.querySelector('[name=nutrition_label]').value.trim(),value:row.querySelector('[name=nutrition_value]').value.trim(),unit:row.querySelector('[name=nutrition_unit]').value.trim()})).filter(v=>v.label&&v.value!=='');const payload={name:fd.get('name').trim(),brand:fd.get('brand').trim(),category:fd.get('category').trim(),package_size:fd.get('package_size')?Number(fd.get('package_size')):null,package_unit:fd.get('package_unit'),pack_count:Number(fd.get('pack_count')),notes:fd.get('notes').trim(),nutrition:{basis:fd.get('nutrition_basis').trim(),serving_size:fd.get('serving_size').trim(),values},source_ids:state.editorSources.map(s=>s.id)};
  setEditorBusy(true);let itemSaved=false;try{const id=form.dataset.id;const item=await api(id?`/api/items/${encodeURIComponent(id)}`:'/api/items',{method:id?'PUT':'POST',body:JSON.stringify(payload)});itemSaved=true;form.dataset.id=item.id;if(!id&&fd.get('initial_price')){try{await api(`/api/items/${item.id}/prices`,{method:'POST',body:JSON.stringify({price:Number(fd.get('initial_price')),observed_on:fd.get('initial_date')||today(),kind:fd.get('initial_kind'),source_id:state.editorSources[0]?.id||null})});}catch(err){await refreshItems();error.innerHTML=errorBox(`Your food was saved, but its first price was not: ${err.message} Close this editor and use “Add price” on the item.`);const initial=form.querySelector('[name=initial_price]');if(initial)initial.disabled=true;return;}}await refreshItems();editor.close();toast(id?'Your food details are updated.':'A new staple, safely in your library.');if(location.hash.startsWith('#imports')){if(state.importSource&&state.extraction)drawImportRows();}else if(location.hash===`#item/${item.id}`){route();}else location.hash=`item/${item.id}`;}catch(err){error.innerHTML=errorBox(err.message+(itemSaved?' The food itself has already been saved.':''));}finally{setEditorBusy(false);}}

function openPriceDialog(id){const item=state.items.find(i=>String(i.id)===String(id));document.querySelector('#small-content').innerHTML=`<form id="price-form" data-id="${e(id)}"><header class="dialog-header"><div><h2 id="small-title">One more price to remember.</h2><p>${e(item?.name||'Food item')} · ${e(item?packageText(item):'')}</p></div><button class="icon-button" type="button" data-action="close-small" aria-label="Close add price">${icon('close')}</button></header><div class="dialog-body"><div class="form-grid"><label class="field"><span>Price (AED)</span><input name="price" type="number" required min="0.01" step="0.01" placeholder="0.00" inputmode="decimal" autofocus></label><label class="field"><span>Date observed</span><input name="observed_on" type="date" required value="${today()}"></label><label class="field full"><span>Price type</span><select name="kind"><option value="regular">Regular shelf price</option><option value="offer">Special offer</option><option value="paid">What I paid</option></select></label><label class="field full"><span>Offer end date <span class="optional">optional</span></span><input name="valid_to" type="date"></label><label class="field full"><span>Notes <span class="optional">optional</span></span><textarea name="notes" placeholder="e.g. Shelf label, branch, or offer conditions"></textarea></label></div><div id="price-error"></div></div><footer class="dialog-footer"><div class="dialog-footer-actions"><button class="button secondary" type="button" data-action="close-small">Cancel</button><button class="button primary" type="submit">Save price</button></div></footer></form>`;document.querySelector('#price-form').addEventListener('submit',async event=>{event.preventDefault();const form=event.target,fd=new FormData(form),button=form.querySelector('[type=submit]'),error=document.querySelector('#price-error');error.innerHTML='';if(fd.get('valid_to')&&fd.get('valid_to')<fd.get('observed_on')){error.innerHTML=errorBox('The end date must be on or after the observation date.');return;}button.disabled=true;try{await api(`/api/items/${encodeURIComponent(id)}/prices`,{method:'POST',body:JSON.stringify({price:Number(fd.get('price')),observed_on:fd.get('observed_on'),valid_to:fd.get('valid_to')||null,kind:fd.get('kind'),notes:fd.get('notes')})});await refreshItems();smallDialog.close();toast('Price added to your notebook.');route();}catch(err){error.innerHTML=errorBox(err.message);}finally{button.disabled=false;}});smallDialog.showModal();}
function confirmDeletePrice(id,itemId){document.querySelector('#small-content').innerHTML=`<header class="dialog-header"><div><h2 id="small-title">Remove this price?</h2><p>This observation will be removed from the table and weekly graph.</p></div><button class="icon-button" data-action="close-small" aria-label="Close confirmation">${icon('close')}</button></header><div class="dialog-body"><p class="section-note">Your food, nutrition facts, and original photos will stay in your library.</p><div id="delete-error"></div></div><footer class="dialog-footer"><div class="dialog-footer-actions"><button class="button secondary" data-action="close-small">Keep price</button><button class="button danger" id="confirm-delete-price">Remove price</button></div></footer>`;document.querySelector('#confirm-delete-price').addEventListener('click',async event=>{event.target.disabled=true;try{await api(`/api/prices/${encodeURIComponent(id)}`,{method:'DELETE'});await refreshItems();smallDialog.close();toast('Price removed.');route();}catch(err){document.querySelector('#delete-error').innerHTML=errorBox(err.message);event.target.disabled=false;}});smallDialog.showModal();}
function showPhoneAccess(){
  const local=['localhost','127.0.0.1','::1','[::1]'].includes(location.hostname),cloud=cloudEnabled(),address=location.href.split('#')[0];
  let explanation;
  if(cloud)explanation=`<p class="section-note">Open this website on your phone and sign in with the same account. Your saved foods, labels, and weekly prices sync between devices.</p><a class="phone-url" href="${e(address)}">${e(address)}</a><p class="section-note">The website itself is public. Your food records and uploaded files are private to your account.</p><p class="section-note">Add it to your home screen from your browser’s share menu. An internet connection is needed to access and save your records.</p>`;
  else if(!local&&state.info.auth_required)explanation=`<p class="section-note">Open this address in your phone’s browser and sign in with your pantry password. Availability away from home depends on how the server is hosted.</p><a class="phone-url" href="${e(location.origin)}">${e(location.origin)}</a><p class="section-note">Add the website to your home screen from your browser’s share menu.</p>`;
  else explanation='<p class="section-note">This address is a preview on this computer. To sync your pantry with your phone, use the connected website and sign in with your account.</p><p class="section-note">The included setup guide explains the free website and private cloud storage setup.</p>';
  document.querySelector('#small-content').innerHTML=`<header class="dialog-header"><div><h2 id="small-title">Your pantry, in your pocket.</h2><p>Phone access & your backups</p></div><button class="icon-button" data-action="close-small" aria-label="Close phone access">${icon('close')}</button></header><div class="dialog-body">${explanation}<a class="button secondary" href="${cloud?'#backup':'/api/backup'}" data-action="backup">${icon('download')}Download a backup</a>${state.info.auth_required?(cloud?'<button class="button subtle" type="button" style="margin-top:18px" data-action="sign-out">Sign out</button>':'<form action="/logout" method="POST" style="margin-top:18px"><button class="button subtle" type="submit">Sign out</button></form>'):''}</div>`;smallDialog.showModal();
}
async function downloadCloudBackup(button){if(state.backupBusy)return;state.backupBusy=true;button.setAttribute('aria-busy','true');toast('Preparing your library backup…');try{await window.PantryCloud.backup();toast('Your backup is ready.');}catch(err){toast(err.message||'Your backup could not be prepared. Please try again.');}finally{state.backupBusy=false;button.removeAttribute('aria-busy');}}
async function signOutCloud(){try{if(!window.pantrySignOut)throw new Error('Sign out is unavailable. Refresh and try again.');await window.pantrySignOut();}catch(err){toast(err.message);}}


document.addEventListener('keydown',event=>{const label=event.target.closest('label[role=button]');if(label&&(event.key==='Enter'||event.key===' ')){event.preventDefault();document.getElementById(label.htmlFor)?.click();}});
document.addEventListener('click',async event=>{
  const button=event.target.closest('[data-action]');if(!button)return;const action=button.dataset.action;
  if(cloudEnabled()&&!state.booted&&action!=='phone-access'){event.preventDefault();toast('Sign in to open your pantry.');return;}
  if(action==='backup'){if(cloudEnabled()){event.preventDefault();await downloadCloudBackup(button);}return;}
  if(action==='sign-out'){event.preventDefault();await signOutCloud();return;}
  if(action==='new-item')await openEditor();
  else if(action==='edit-item')await openEditor(button.dataset.id);
  else if(action==='phone-access')showPhoneAccess();
  else if(action==='close-editor'){if(state.editorBusy){photoMessage('Please wait for the current save to finish.');return;}editor.close();}
  else if(action==='paste-photos')await pastePhotos();
  else if(action==='close-small')smallDialog.close();
  else if(action==='add-price')openPriceDialog(button.dataset.id);
  else if(action==='delete-price')confirmDeletePrice(button.dataset.id,button.dataset.item);
  else if(action==='add-nutrient')document.querySelector('#nutrition-inputs').insertAdjacentHTML('beforeend',nutritionRow());
  else if(action==='remove-nutrient')button.closest('.nutrition-input-row').remove();
  else if(action==='remove-photo'){if(state.editorBusy){photoMessage('Please wait for the current save to finish.');return;}state.editorSources=state.editorSources.filter(s=>String(s.id)!==String(button.dataset.id));drawPhotoThumbs();}
  else if(action==='apply-nutrition'){const s=state.nutritionSuggestion,form=document.querySelector('#item-form');form.elements.nutrition_basis.value=s.basis||'';form.elements.serving_size.value=s.serving_size||'';document.querySelector('#nutrition-inputs').innerHTML=s.values.map(nutritionRow).join('');button.textContent='Applied — review the values below';button.disabled=true;}
  else if(action==='review-source'){const source=state.sources.find(s=>String(s.id)===String(button.dataset.id));if(source)await extractFlyer(source);}
  else if(action==='add-import-row'){state.importRows.push({label:'Price entered manually',price:'',item_id:'',page:'',selected:false});drawImportRows();const rows=document.querySelectorAll('.review-row');rows[rows.length-1]?.querySelector('select')?.focus();}
  else if(action==='remove-import-row'){state.importRows.splice(Number(button.dataset.index),1);drawImportRows();}
  else if(action==='close-import'){state.importSource=null;state.extraction=null;state.importRows=[];document.querySelector('#import-workspace').innerHTML='';}
});
editor.addEventListener('cancel',event=>{if(state.editorBusy){event.preventDefault();photoMessage('Please wait for the current save to finish.');}});
document.querySelector('#phone-access').addEventListener('click',showPhoneAccess);
async function route(){if(!state.booted)return;const version=++state.routeVersion;const hash=location.hash.slice(1)||'library';if(hash.startsWith('item/'))await renderDetail(hash.slice(5),version);else if(hash==='imports')await renderImports(version);else renderLibrary();window.scrollTo({top:0,behavior:'instant'});}
window.addEventListener('hashchange',route);
async function init(){document.querySelectorAll('[data-icon]').forEach(node=>{node.innerHTML=icon(node.dataset.icon);});try{await (window.pantryCloudReady||Promise.resolve());const [itemsResult,infoResult,sourcesResult]=await Promise.allSettled([api('/api/items'),api('/api/info'),api('/api/sources')]);if(itemsResult.status!=='fulfilled')throw itemsResult.reason;state.items=itemsResult.value.items||[];if(infoResult.status==='fulfilled')state.info=infoResult.value;if(sourcesResult.status==='fulfilled')state.sources=sourcesResult.value.sources||[];updateCounts();state.booted=true;if(cloudEnabled()){document.querySelectorAll('[data-action=backup]').forEach(link=>link.setAttribute('href','#backup'));}if(state.info.auth_required){const link=document.createElement(cloudEnabled()?'div':'form');if(cloudEnabled())link.innerHTML='<button class="quiet-button" type="button" data-action="sign-out">Sign out</button>';else{link.action='/logout';link.method='POST';link.innerHTML='<button class="quiet-button" type="submit">Sign out</button>';}document.querySelector('.sidebar-bottom').insertBefore(link,document.querySelector('.sidebar-bottom p'));}route();}catch(err){main.innerHTML=`<div class="page-heading"><div><div class="eyebrow">YOUR FOOD NOTEBOOK</div><h1>Let’s reconnect.</h1><p class="subtitle">Your pantry could not be opened just yet.</p></div></div>${errorBox(err.message)}<button class="button primary" onclick="location.reload()">Try again</button>`;}}
init();
